    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Next char must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(field)
                        if i < len(line):
                            i += 1  # Skip comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip comma

    return fields

